css:
.dcw-split.is-center { align-items: center; }
.dcw-grid-2 { display: grid; grid-template-columns: 1fr 1fr; grid-column-gap: 48px; grid-row-gap: 40px; }
.dcw-badge { display: inline-block; padding: 4px 10px; border: 1px solid #0a524e; border-radius: 999px; color: #0a524e; font-size: 11px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; white-space: nowrap; }
.dcw-fig-num.is-teal { color: #0f6e68; }
.dcw-fig-text.is-xs { font-size: 12.5px; }
.dcw-strip-wrap { margin-top: 32px; padding-top: 18px; border-top: 1px solid #e2e2e2; }
.dcw-strip-label { margin-bottom: 14px; color: #111111; font-size: 15px; font-weight: 600; }
.dcw-strip-hint { margin-left: 8px; color: #5f5f5f; font-size: 13px; font-weight: 400; }
.dcw-strip { display: flex; grid-column-gap: 18px; overflow-x: auto; padding-bottom: 14px; scroll-snap-type: x mandatory; }
.dcw-strip-item { flex: 0 0 150px; scroll-snap-align: start; }
.dcw-sketch { max-width: 380px; }
.dcw-sketch-img { display: block; width: 100%; aspect-ratio: 4 / 5; object-fit: cover; border: 1px solid #e2e2e2; border-radius: 14px; }
.dcw-decision-title.is-spaced { margin-top: clamp(40px, 5vw, 64px); padding-top: clamp(40px, 5vw, 64px); border-top: 1px solid #e2e2e2; }
.dcw-notice { display: flex; align-items: flex-start; grid-column-gap: 14px; max-width: 760px; padding: 16px 18px; border: 1px solid #c9c9c9; border-left: 4px solid #0f6e68; border-radius: 8px; background-color: #ffffff; }
.dcw-ideas { display: grid; grid-template-columns: 1fr 1fr; grid-column-gap: 10px; grid-row-gap: 10px; width: 100%; }
.dcw-idea { padding: 12px 14px; border: 1px solid #e2e2e2; border-radius: 10px; background-color: #ffffff; }
.dcw-idea.is-picked { border-color: #0f6e68; background-image: linear-gradient(160deg, #e3f2ef, #d2ebe5); }
.dcw-idea-t { color: #111111; font-size: 15px; font-weight: 500; }
.dcw-idea-s { color: #5f5f5f; font-size: 13px; }
.dcw-idea-s.is-picked { color: #0a524e; }
.dcw-ab { display: grid; grid-template-columns: 1fr 1fr; grid-column-gap: clamp(24px, 4vw, 56px); grid-row-gap: 40px; margin-top: 32px; }
.dcw-ab-opts { display: grid; grid-template-columns: 1fr 1fr; grid-column-gap: clamp(14px, 2vw, 24px); width: 100%; }
@media screen and (max-width: 991px) { .dcw-ab { grid-template-columns: 1fr; } }
@media screen and (max-width: 767px) { .dcw-grid-2 { grid-template-columns: 1fr; } .dcw-ideas { grid-template-columns: 1fr; } }
